map $http_user_agent $cli_request {
    default 0;
    ~*(curl|wget|httpie|powershell|python-requests|Go-http-client|git-annex) 1;
}

upstream forgejo_upstream {
    server forgejo:3000 max_fails=3 fail_timeout=5s;
}

upstream s3_fetcher_upstream {
    server s3_fetcher:9000 max_fails=3 fail_timeout=5s;
}

server {

    listen 443 ssl;
    http2 on;
    server_name datalad-test.lan.local;

    ssl_certificate     /ssl/certs/local-cert.pem;
    ssl_certificate_key /ssl/private/local-key.pem;

    set $PROXY_SERVICE_URI oauth2-proxy;

    location @unauthorized {
        if ($cli_request) {
            return 401;
        }

        return 302 /oauth2/sign_in;
    }



    # -----------------------
    # Git Service
    # -----------------------
    location / {

        # # Enforce authentication
        auth_request /oauth2/auth;

        if ($http_authorization = "") {
            error_page 401 = @unauthorized;
        }

        proxy_set_header Connection $http_connection;
        proxy_set_header Upgrade $http_upgrade;
        proxy_set_header Host $host;
        proxy_set_header X-Real-IP $remote_addr;
        proxy_set_header X-Forwarded-For $proxy_add_x_forwarded_for;
        proxy_set_header X-Forwarded-Proto $scheme;

        # REMOVE Authorization header before sending to backend, else git requests login creds
        proxy_set_header Authorization "";

        client_max_body_size 512M;

        proxy_pass http://forgejo_upstream;
    }


    # -----------------------
    # OAuth2 endpoints
    # -----------------------

    location /oauth2/ {

        proxy_buffer_size 16k;
        proxy_buffers 8 16k;
        proxy_busy_buffers_size 32k;

        proxy_pass       http://oauth2-proxy:4180;
        proxy_set_header Host                    $host;
        proxy_set_header X-Real-IP               $remote_addr;
        proxy_set_header X-Scheme                $scheme;
        proxy_set_header X-Auth-Request-Redirect $request_uri;
    }

    # Endpoint used by auth_request
    location = /oauth2/auth {
        internal;

        proxy_buffer_size 16k;
        proxy_buffers 8 16k;

        auth_request_set $user  $upstream_http_x_auth_request_user;
        auth_request_set $token $upstream_http_x_auth_request_access_token;

        proxy_pass       http://oauth2-proxy:4180;
        proxy_set_header Host              $host;
        proxy_set_header X-Real-IP         $remote_addr;
        proxy_set_header X-Scheme          $scheme;

        proxy_set_header Content-Length    "";
        proxy_pass_request_body off;

        # Capture token from oauth2-proxy response
        auth_request_set $access_token $upstream_http_x_auth_request_access_token;
    }


location /whoami/token {
    auth_request /oauth2/auth;

    add_header Content-Type text/plain;

    proxy_pass http://oauth2-proxy:4180/oauth2/auth;
    proxy_set_header Host $host;
    proxy_set_header X-Real-IP $remote_addr;
    proxy_set_header X-Scheme $scheme;

    proxy_set_header Content-Length "";
    proxy_pass_request_body off;
}

    # -----------------------
    # Protected downloads
    # -----------------------

    location /downloads/ {

        proxy_buffer_size 16k;
        proxy_buffers 8 16k;
        proxy_busy_buffers_size 32k;

        # Streaming settings
        proxy_buffering off;
        proxy_request_buffering off;
        proxy_http_version 1.1;

        # Enforce authentication
        auth_request /oauth2/auth;

        # If unauthenticated, redirect to login
        if ($http_authorization = "") {
            error_page 401 = @unauthorized;
        }

        # Capture identity info for backend
        auth_request_set $user  $upstream_http_x_auth_request_user;
        auth_request_set $email $upstream_http_x_auth_request_email;
        auth_request_set $authz $upstream_http_authorization;

        # Pass identity to fetcher
        proxy_set_header X-Authenticated-User  $user;
        proxy_set_header X-Authenticated-Email $email;
        proxy_set_header Authorization         $authz;

        # Backend fetcher
        proxy_pass http://s3_fetcher_upstream;

    }

}
